mapper.select:
SELECT REVIEW_ID, RESERVATION_ID, RATING, CONTENT, CREATED_AT, REPLY_CONTENT, REPLIED_AT, ADMIN_ID
  FROM TBL_REVIEW
 WHERE REVIEW_ID = #{reviewId}

SELECT P.PHOTO_ID, P.REVIEW_ID, P.FILE_PATH, P.SORT_ORDER FROM TBL_REVIEW_PHOTO P
JOIN TBL_REVIEW R ON R.REVIEW_ID = P.REVIEW_ID JOIN TBL_RESERVATION RS ON RS.RESERVATION_ID = R.RESERVATION_ID JOIN TBL_MOVE_REQUEST M ON M.REQUEST_ID = RS.REQUEST_ID WHERE M.MEMBER_ID = #{memberId}
ORDER BY P.REVIEW_ID, P.SORT_ORDER

SELECT P.PHOTO_ID, P.REVIEW_ID, P.FILE_PATH, P.SORT_ORDER FROM TBL_REVIEW_PHOTO P
JOIN TBL_REVIEW R ON R.REVIEW_ID = P.REVIEW_ID JOIN TBL_RESERVATION RS ON RS.RESERVATION_ID = R.RESERVATION_ID JOIN TBL_MOVE_REQUEST M ON M.REQUEST_ID = RS.REQUEST_ID
WHERE P.PHOTO_ID = #{photoId}
AND M.MEMBER_ID = #{memberId}

SELECT ,
       (SELECT MAX(REVIEW_ID) FROM TBL_REVIEW WHERE RESERVATION_ID = RS.RESERVATION_ID) AS REVIEW_ID
  FROM TBL_RESERVATION RS

 WHERE RS.RESERVATION_ID = #{reservationId}
   AND M.MEMBER_ID = #{memberId}

mapper.update:
UPDATE TBL_REVIEW
   SET REPLY_CONTENT = #{content},
       REPLIED_AT = SYSDATE,
       ADMIN_ID = #{adminId}
 WHERE REVIEW_ID = #{reviewId}
